@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;
const PI: f32 = 3.141592654;
fn hash(p: vec2f) -> f32 { return fract(sin(dot(p, vec2f(127.1,311.7))) * 43758.5453); }
fn noise(p: vec2f) -> f32 {
  let i = floor(p); let f = fract(p); let u = f*f*(3.0-2.0*f);
  return mix(mix(hash(i),hash(i+vec2f(1,0)),u.x),mix(hash(i+vec2f(0,1)),hash(i+vec2f(1,1)),u.x),u.y);
}
fn fbm(p: vec2f) -> f32 { return noise(p)*0.57+noise(p*2.07+3.1)*0.28+noise(p*4.13-1.6)*0.15; }
fn atlas(uv: vec2f) -> vec3f { return textureSampleLevel(inputTexture,inputSampler,clamp(uv,vec2f(0.001),vec2f(0.999)),0.0).rgb; }

fn rotateToEye(p: vec3f, g: vec2f) -> vec3f {
  let c=cos(g.x);let s=sin(g.x); let q=vec3f(c*p.x-s*p.z,p.y,s*p.x+c*p.z);
  let a=cos(g.y);let b=sin(g.y);return vec3f(q.x,a*q.y-b*q.z,b*q.y+a*q.z);
