  let lip=exp(-pow((e-mix(0.082,0.106,upper))/mix(0.105,0.134,upper),2.0));
  let crease=exp(-pow((e-mix(0.31,0.27,upper)-0.027*sin(p.x*4.2))/0.067,2.0));
