  let safe=clamp(skinUV,vec2f(0.003),vec2f(0.997));
  let scan=atlas(vec2f(safe.x,safe.y*2.0/7.0));
  // Past the limits of the lid scan, sample the unbroken cheek area in two
  // tangent directions rather than dragging the last column of texels sideways.
  let cheekUV=vec2f(0.5)+0.37*vec2f(atan2(p.x,p.z+0.18),atan2(p.y,length(p.xz+vec2f(0,0.18))));
  let wrapped=1.0-abs(fract(cheekUV*0.5)*2.0-1.0);
  let cheek=atlas(vec2f(0.005+wrapped.x*0.99,5.0/7.0+(0.005+wrapped.y*0.99)*2.0/7.0));
  let border=min(min(u,1.0-u),min(v,1.0-v));
  return mix(cheek,scan,smoothstep(-0.005,0.05,border));
}
fn shadeSkin(p:vec3f,rd:vec3f,cl:f32,g:vec2f)->vec3f {
  let edge=aperture(p.xy,cl,g);
  let margin=exp(-pow(max(edge,0.0)/0.14,2.0));
  let raw=lidMap(p,cl,g);
  let blood=clamp((raw.r-raw.g*1.7)/max(raw.r,0.04),0.0,1.0);
  let moist=clamp(blood*0.60+margin*0.52,0.0,1.0)*params.wetness;
  let base=raw*mix(vec3f(1),vec3f(0.88,0.64,0.57),params.skinRedness*blood);
  let n=tissueNormal(p,cl,g);
  let tangent=normalize(cross(select(vec3f(0,1,0),vec3f(1,0,0),abs(n.y)>0.9),n));
  let bitangent=cross(n,tangent);
  let weights=vec3f(0.32,0.52,0.16);
  let relief=dot(raw,weights);
  let dx=dot(lidMap(p+0.003*tangent,cl,g),weights)-relief;
  let dy=dot(lidMap(p+0.003*bitangent,cl,g),weights)-relief;
  let normal=normalize(n-params.poreStrength*3.2*(dx*tangent+dy*bitangent));
  let rough=mix(params.skinRoughness,0.28,moist);
  let direct=lightSurface(base,normal,-rd,rough,0.82,params.translucency);
  let reflection=reflect(rd,normal);
  let film=roomRadiance(reflection)*moist*moist*0.067;
  let lower=lidEdges(p.x,cl,g).y;
  let meniscus=exp(-pow((p.y-lower+0.010)/0.018,2.0))*(1.0-smoothstep(0.76,0.91,abs(p.x)));
  let tear=meniscus*roomRadiance(reflect(rd,normalize(normal+vec3f(0,0.37,0))))*0.065*params.wetness;
