  var ro=vec3f(-0.63,0.19,4.38);var aim=vec3f(0.015,-0.01,0.57);var fov=28.0;
  if(params.viewOverride>0.5){ro=params.viewEye;aim=params.viewTarget;fov=params.viewFov;}
  let forward=normalize(aim-ro);let right=normalize(cross(forward,vec3f(0,1,0)));let up=cross(right,forward);
  let screen=(uv-0.5)*vec2f(aspect,-1.0)*2.0/max(params.eyeSize,0.1);
  let rd=normalize(forward+(right*screen.x+up*screen.y)*tan(fov*PI/360.0));
  let te=sphere(ro,rd,vec3f(0),1.0);
  let cap=sphere(rotateToEye(ro,g),rotateToEye(rd,g),vec3f(0,0,0.44),0.618);
  let firstEye=min(te,cap);
  let ts=marchTissue(ro,rd,cl,g,min(firstEye,7.0));
  var color=vec3f(0.004,0.0045,0.0055);
  if(ts<firstEye && ts<99.0){color=shadeSkin(ro+rd*ts,rd,cl,g);}
  else if(te<99.0){color=shadeGlobe(ro,rd,te,g,cl,time);}
  // The nasal caruncle is a small separate body partly occluded by the lower lid.
  let ductCenter=vec3f(-0.843,-0.052,0.545);
  let axes=vec3f(0.112,0.061,0.087);
  let ductRay=rd/axes;
  let ductT=sphere((ro-ductCenter)/axes,normalize(ductRay),vec3f(0),1.0)/length(ductRay);
  let ductP=ro+rd*ductT;
  if(ductT<min(firstEye,ts) && length((ductP-ductCenter)/axes)<1.01){
    let normal=normalize((ductP-ductCenter)/(axes*axes));
    let fleck=fbm(ductP.xy*85.0);
    let base=mix(vec3f(0.18,0.034,0.032),vec3f(0.41,0.112,0.085),fleck);
    color=lightSurface(base,normal,-rd,0.33,0.68,params.translucency)+roomRadiance(reflect(rd,normal))*0.032*params.wetness;
  }
  color*=exp2(params.exposure)*params.amount;
  // Filmic highlight shoulder in linear light. The Output node applies the sRGB transfer once.
  color=(color*(2.51*color+0.03))/(color*(2.43*color+0.59)+0.14);
  let vignette=1.0-0.18*smoothstep(0.35,1.0,length((uv-0.5)*vec2f(1,1.2)));
  return vec4f(clamp(color*vignette,vec3f(0),vec3f(1)),1);
}
